mapper.insert:
INSERT INTO TBL_ATTENDANCE_M (
attendance_dt,
created_at_dtm,
user_sq
) VALUES (
CURDATE(),
NOW(),
#{userSq}
)

mapper.select:
SELECT DATE_FORMAT(attendance_dt, '%Y-%m-%d')
FROM TBL_ATTENDANCE_M
WHERE user_sq = #{userSq}
AND YEAR(attendance_dt) = #{year}
AND MONTH(attendance_dt) = #{month}
ORDER BY attendance_dt ASC
